"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["27434"],{11899(e){e.exports=JSON.parse('{"id":"FIN-534","slug":"tax-deduction","term":"Tax Deduction","also_known_as":[],"difficulty":"Beginner","definition":"A tax deduction is an amount that can be subtracted from income before tax is calculated, which reduces taxable income and therefore the tax owed.","explanation":["Deductions lower the income on which tax is charged. Their value depends on the taxpayer\'s marginal tax rate, the rate paid on their last unit of income.","For example, a deduction of 1,000 for someone in a 20% tax bracket reduces their tax bill by 200. For someone in a 40% bracket, the same deduction saves 400. This is why deductions tend to be worth more to people with higher incomes.","Common deductions, depending on the country, include contributions to pensions or retirement accounts, certain business or work-related expenses, interest on some types of loans, charitable donations and some medical or education costs.","Deductions are different from tax credits. A deduction reduces the income that is taxed; a credit reduces the tax itself, unit for unit. A 1,000 tax credit saves 1,000 of tax regardless of the taxpayer\'s rate, making it more valuable than a 1,000 deduction for most people.","Tax rules usually require records to support deductions, and some systems let taxpayers choose between claiming a standard deduction and listing their actual deductions."],"note":"","total":1500,"prev":{"slug":"tax-credit","term":"Tax Credit"},"next":{"slug":"tax-deferred-growth","term":"Tax-Deferred Growth"}}')}}]);